set +o posix

quiet_safe_cd() {
  cd "$1" &>/dev/null || {
    echo "Error: failed to cd to $1" >&2
    exit 1
  }
}

absdir() {
  quiet_safe_cd "${1%/*}/" && pwd -P
}

dirbasepath() {
  local dir="$1"
  local base="${2##*/}"
  echo "${dir}/${base}"
}

realpath() {
  local path="$1"
  local dir
  local dest

  dir="$(absdir "${path}")"
  path="$(dirbasepath "${dir}" "${path}")"

  while [[ -L "${path}" ]]
  do
    dest="$(readlink "${path}")"
    if [[ "${dest}" == "/"* ]]
    then
      path="$
